public sealed class ArgumentList : IBaseArgumentListNode
{
    public string? OpenParenToken { get; set; }
    public List<Argument> Arguments { get; } = new();
    public string? CloseParenToken { get; set; }

    public ArgumentList() { }

    public void AddUsingNamespace(string ns) { }

    public void WriteOutput(IOutputContext outputContext)
    {
        Tk.W(outputContext, OpenParenToken);
        for (var i = 0; i < Arguments.Count; i++)
        {
            if (i > 0) outputContext.Write(", ");
            Arguments[i].WriteOutput(outputContext);
        }
        Tk.W(outputContext, CloseParenToken);
    }
}

