    public List<IExpressionNode> ErrorCodes { get; } = new();
    public string? EndOfDirectiveToken { get; set; }
    public ISyntaxNode? IsActive { get; set; }

    public PragmaWarningDirectiveTrivia(ISyntaxNode isActive)
    {
        IsActive = isActive;
    }

    public void AddUsingNamespace(string ns) { }

    public void WriteOutput(IOutputContext outputContext)
    {
        Tk.W(outputContext, HashToken);
        Tk.W(outputContext, PragmaKeyword);
        Tk.W(outputContext, WarningKeyword);
        Tk.W(outputContext, DisableOrRestoreKeyword);
        for (var i = 0; i < ErrorCodes.Count; i++)
        {
            if (i > 0) outputContext.Write(", ");
            ErrorCodes[i].WriteOutput(outputContext);
        }
        Tk.W(outputContext, EndOfDirectiveToken);
        IsActive?.WriteOutput(outputContext);
    }
}

